import{_ as l,c as n,o as e,a7 as s}from"./chunks/framework.Vx-M4LRp.js";const u=JSON.parse('{"title":"工具","description":"","frontmatter":{"outline":[1,8]},"headers":[],"relativePath":"blog/read/阮一峰期刊.md","filePath":"blog/read/阮一峰期刊.md","lastUpdated":1794799499000}'),i={name:"blog/read/阮一峰期刊.md"};function r(t,a,p,o,h,c){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to “工具”">​</a></h1><ul><li><a href="https://github.com/oomol-lab/open-connector" target="_blank" rel="noreferrer">密码连接网关OpenConnector</a><ul><li>它跟 AI Agent 配套使用，主要解决 AI 自动化工具（比如 OpenClaw）的授权问题</li></ul></li><li><a href="https://github.com/vudsen/ai-disk-cleaner" target="_blank" rel="noreferrer">ai-disk-cleaner</a><ul><li>开源的 Windows 磁盘清理工具，用 AI 分析垃圾文件</li></ul></li><li><a href="https://github.com/awdr74100/figwright" target="_blank" rel="noreferrer">Figwright</a><ul><li>一个 MCP 服务器，让 Claude Code、Cursor、Codex 等 AI 代理直接操作 Figma，能读设计稿也能画设计稿</li></ul></li><li><a href="https://watermarkzero.org/" target="_blank" rel="noreferrer">Gemini 生成图片的可见水印去除工具，图片不需要上传到服务器，直接在本地浏览器处理</a></li><li><a href="https://github.com/PDFCraftTool/pdfcraft" target="_blank" rel="noreferrer">PDFCraft</a><ul><li>纯浏览器的 PDF 开源工具集，目前有80多个工具</li></ul></li><li><a href="https://www.thiings.co/" target="_blank" rel="noreferrer">Thiings</a> 一个搜索下载 3D 图标的网站，现有近3000个图标</li><li><a href="https://subway.cuvii.dev/" target="_blank" rel="noreferrer">中国城市地铁可视化</a></li><li><a href="https://github.com/wanghongenpin/proxypin/blob/main/README_CN.md" target="_blank" rel="noreferrer">ProxyPin开源免费抓包工具支持Windows、Mac、Android、IOS、Linux 全平台系统</a></li><li><a href="https://github.com/WANGXIN-567/weread-book-exporter" target="_blank" rel="noreferrer">微信读书全书无损导出工具，抓取微信读书 Web 端已购或会员书籍全文，一键导出为 PDF、EPUB 以及 Markdown 笔记</a></li><li><a href="https://synthid.com/" target="_blank" rel="noreferrer">谷歌官方推出的 AI 识别工具。只要上传文件，它会识别是否包含 SynthID。如果有，该文件就是 AI 生成</a></li><li><a href="https://guokaigdg.github.io/naive-icons/#icons" target="_blank" rel="noreferrer">手绘风格的 SVG 图标库 Naive Icons</a><ul><li><a href="https://github.com/guokaigdg/naive-icons/tree/main" target="_blank" rel="noreferrer">git仓库</a></li></ul></li><li><a href="https://artmuseum.artfrompixels.com/" target="_blank" rel="noreferrer">艺术史步行之旅</a>:这个网站将维基百科上面的画作，按照艺术流派，变成可以步行参观的 3D 画廊.动画效果做的很棒</li></ul><hr><h1 id="文章" tabindex="-1">文章 <a class="header-anchor" href="#文章" aria-label="Permalink to “文章”">​</a></h1><ul><li><a href="https://blog.algomaster.io/p/scaling-a-system-from-0-to-10-million-users" target="_blank" rel="noreferrer">如何将系统从0扩展到1000万+用户</a> 文末有作者的博客入口</li><li><a href="https://restofworld.org/2025/ai-chatbot-china-sick/zh/" target="_blank" rel="noreferrer">我的妈妈和 DeepSeek 博士</a></li><li><a href="https://scroll-driven-animations.style/" target="_blank" rel="noreferrer">网页滚动的动画效果</a></li></ul><h1 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to “其他”">​</a></h1><ul><li>3D版看不见的城市 <ul><li>Claude Opus 5.5 的实现 <a href="https://p.migdal.pl/invisible-cities-opus-5.5/" target="_blank" rel="noreferrer">交互</a> <a href="https://github.com/stared/invisible-cities-opus-5.5" target="_blank" rel="noreferrer">代码</a></li><li>GPT-6 Astra 的实现 <a href="https://p.migdal.pl/invisible-cities-astra/" target="_blank" rel="noreferrer">交互</a> <a href="https://github.com/stared/invisible-cities-astra" target="_blank" rel="noreferrer">实现</a></li><li></li></ul></li></ul><hr><h1 id="ai相关" tabindex="-1">AI相关 <a class="header-anchor" href="#ai相关" aria-label="Permalink to “AI相关”">​</a></h1><h2 id="对ai的态度" tabindex="-1">对AI的态度 <a class="header-anchor" href="#对ai的态度" aria-label="Permalink to “对AI的态度”">​</a></h2><p>1、AI 会大大增强程序员的生产力，并创造过去不可能的产品。</p><p>2、AI 本质是生产力工具，跟高级语言、云服务、开源代码等是一个性质。</p><p>3、写代码的门槛会降低，更多的人会进入 IT 行业，软件市场将变大。</p><p>4、AI 推动行业发展，将为所有人带来更多的增长、产品和机会。</p><p>5、我们要成为这个过程的一部分，需要让自己积极主动，不断更新技能，接受新工具。</p><h2 id="ai-言论" tabindex="-1">AI 言论 <a class="header-anchor" href="#ai-言论" aria-label="Permalink to “AI 言论”">​</a></h2><ul><li>AI 的真正风险不在于使人懒惰，而在于让&quot;懒惰&quot;看起来像&quot;高效&quot;。花十分钟读一篇摘要，把它发到社交媒体上，你感觉自己很高效，但实际上什么都没记住。</li><li>现在只需几秒钟，AI 就能找到代码错误，或者读取整本使用手册。这些都节省了过去浪费在无意义学习、手工输入的大量时间。 与此同时，AI 也让我们失去了一些东西，就是那种你必须仔细阅读、理解每一行代码的投入。你有捷径可走，就不会下苦功专研了。- <a href="https://comuniq.xyz/post?t=1439" target="_blank" rel="noreferrer">《80年代的编程体验》</a></li><li>有人问，AI 编写的代码，我根本不理解，公司却要我发布它，怎么办？我的回答是，不要让 AI 设计代码，而要让它实现你已经设计好的代码。</li><li>大模型会将你从一个编写代码的程序员，转变为一个管理上下文、剔除无关信息、编写详细提示词的程序员。</li><li>很多技术出错，并不是太大的问题。GPS 出错，我很快会发现地点不对；Netflix 推荐的电影不好看，我就不看了。但 AI 就不同了，它越先进，就越难知道它是否出错，因为我们会用 AI 去完成那些我们自己无法完成、也无法验证的任务。一旦 AI 出错，我们只能不停召唤更强大 的 AI，希望咒语能够奏效。欢迎来到魔法师时代</li><li>未来，你还是需要学习编程。因为你需要能够准确地告诉 AI 你想要什么，了解计算机的工作原理有助于你编写更精确的提示和指令。</li></ul><h1 id="_416期" tabindex="-1">416期 <a class="header-anchor" href="#_416期" aria-label="Permalink to “416期”">​</a></h1><h2 id="编程已经面目全非" tabindex="-1">编程已经面目全非 <a class="header-anchor" href="#编程已经面目全非" aria-label="Permalink to “编程已经面目全非”">​</a></h2><h3 id="_1-代码审查-code-review-将消失。" tabindex="-1">（1）代码审查（Code review）将消失。 <a class="header-anchor" href="#_1-代码审查-code-review-将消失。" aria-label="Permalink to “（1）代码审查（Code review）将消失。”">​</a></h3><ul><li>人工审查代码已经没意义了。因为人类跟不上 AI 生成代码的速度，无法在合理的时间内，发现 AI 代码中的 Bug。</li><li>人类未来只能审查整个系统的组成或架构是否合理，而绝不会像现在这样，通过 PR 逐行审查代码。</li></ul><h3 id="_2-单元测试可能会消失。" tabindex="-1">（2）单元测试可能会消失。 <a class="header-anchor" href="#_2-单元测试可能会消失。" aria-label="Permalink to “（2）单元测试可能会消失。”">​</a></h3><ul><li>AI 可以随时改变代码的整个实现，再去测试一个个代码单元，就没意义了。也许下次迭代，整栋楼就会重建，何必再去检查单块砖头。</li><li>将来的项目可能只有接口测试、集成测试、系统测试，而不会保留单元测试。</li></ul><h3 id="_3-软件开发的重点不再是写代码。" tabindex="-1">（3）软件开发的重点不再是写代码。 <a class="header-anchor" href="#_3-软件开发的重点不再是写代码。" aria-label="Permalink to “（3）软件开发的重点不再是写代码。”">​</a></h3><ul><li>代码将来由 AI 负责，程序员的工作重点将移到代码以外的其他环节：如何用软件解决业务问题、了解软件如何实现、如何发布软件、如何收集反馈等等。</li></ul><h3 id="_4-bug-的性质也变了。" tabindex="-1">（4）Bug 的性质也变了。 <a class="header-anchor" href="#_4-bug-的性质也变了。" aria-label="Permalink to “（4）Bug 的性质也变了。”">​</a></h3><ul><li>大多数 Bug 不再是代码 Bug，而是需求提错了或表达不准确。</li></ul><h3 id="_5-软件开源不再能提升质量。" tabindex="-1">（5）软件开源不再能提升质量。 <a class="header-anchor" href="#_5-软件开源不再能提升质量。" aria-label="Permalink to “（5）软件开源不再能提升质量。”">​</a></h3><ul><li>以前，代码开源的一个理由是&quot;只要关注的人足够多，所有 Bug 都能被发现&quot;。</li><li>这句话依然成立，但是现在即使你不开源，AI 也能帮你发现 Bug。</li></ul><h3 id="_6-敏捷编程会死亡。" tabindex="-1">（6）敏捷编程会死亡。 <a class="header-anchor" href="#_6-敏捷编程会死亡。" aria-label="Permalink to “（6）敏捷编程会死亡。”">​</a></h3><ul><li>敏捷编程的各种方法（Agile、Scrum 等），都意义不大了，AI 的生成速度决定了项目的开发时间，你所要做的就是把工单直接推给 AI。</li></ul><h3 id="_7-项目分工将改变。" tabindex="-1">（7）项目分工将改变。 <a class="header-anchor" href="#_7-项目分工将改变。" aria-label="Permalink to “（7）项目分工将改变。”">​</a></h3><ul><li>以前，项目组一般包括三种角色：项目经理（PM）、设计师（Designer）、工程人员（Engineer）。</li><li>以后，这种三元架构将消失。有了 AI， 一个人可以兼任多个角色。</li></ul><h3 id="_8-好代码-的概念将消失。" tabindex="-1">（8）&quot;好代码&quot;的概念将消失。 <a class="header-anchor" href="#_8-好代码-的概念将消失。" aria-label="Permalink to “（8）&quot;好代码&quot;的概念将消失。”">​</a></h3><ul><li>以前，&quot;好代码&quot;的标准是便于人类阅读理解、方便重构、开发维护效率较高的代码。</li><li>但是，你已经不读代码、不直接修改和维护大部分代码，&quot;好代码&quot;的存在前提就消失了。</li></ul><h3 id="_9-代码风格规范和-linter-工具-也没意义了。" tabindex="-1">（9）代码风格规范和 linter 工具，也没意义了。 <a class="header-anchor" href="#_9-代码风格规范和-linter-工具-也没意义了。" aria-label="Permalink to “（9）代码风格规范和 linter 工具，也没意义了。”">​</a></h3><ul><li>AI 会在乎代码风格吗：每行不超过80个字符、有没有换行符、缩进是 tab 键还是空格键......？</li></ul><h3 id="_10-ui-将变得不重要。" tabindex="-1">（10）UI 将变得不重要。 <a class="header-anchor" href="#_10-ui-将变得不重要。" aria-label="Permalink to “（10）UI 将变得不重要。”">​</a></h3><ul><li>一方面，未来的很多 UI 是给 AI 使用的，而 AI 只需要 API，不需要精致的 UI。</li><li>另一方面，如果代码的生成速度极快，那么用户界面（UI）将实时生成。许多 UI 之所以存在，是因为软件无法确定你想要什么。菜单、设置页、仪表盘、过滤器，都是为了帮助用户快速确定需求。用户通过语言明确了需求，AI 就可以实时为他生成定制的 UI。</li></ul><h3 id="_11-token-为王。" tabindex="-1">（11）Token 为王。 <a class="header-anchor" href="#_11-token-为王。" aria-label="Permalink to “（11）Token 为王。”">​</a></h3><ul><li>谁能够负担更多的 Token，谁的软件就更好。如果你没有足够的 Token，你就开发不出最优秀的软件。</li></ul><h1 id="_405期" tabindex="-1">405期 <a class="header-anchor" href="#_405期" aria-label="Permalink to “405期”">​</a></h1><h2 id="如何破坏一个组织" tabindex="-1">如何破坏一个组织 <a class="header-anchor" href="#如何破坏一个组织" aria-label="Permalink to “如何破坏一个组织”">​</a></h2><ul><li>官僚主义：只要助长官僚主义，越严重越好，就会让组织的效率变差，难以有效运作，从而起到破坏组织的作用</li></ul><blockquote><p>摧毁一个组织最有效的方法就是使其官僚化。</p><p>每一次毫无意义的会议，每一份需要多个签名的表格，每一个原本只需六分钟最终完成却耗时六周的流程。层层叠叠的规章制度会扼杀了实际工作</p></blockquote><ul><li>小册子列出了一些具体做法。</li></ul><ol><li>绝不要自己做决定，要提交给委员会，由委员会做决定。</li><li>对任何文件的具体措辞讨价还价。</li><li>一遇到重要的事情，就提议召开会议。</li><li>绝不通融，坚持一切严格按流程办事。</li><li>文件要尽量冗长。</li><li>增加办事程序和审批流程。</li></ol><p>只要坚持做到上面六点，就可以破坏一个组织，大到国家，小到团队。</p><h1 id="_398期" tabindex="-1">398期 <a class="header-anchor" href="#_398期" aria-label="Permalink to “398期”">​</a></h1><ul><li><a href="https://www.sina.cn/news/detail/5279286413232198.html" target="_blank" rel="noreferrer">行为经济学诱饵</a></li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>行为经济学家丹·艾瑞里，有一天闲逛《经济学人》官网。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>他在订阅页面上，看到了三个选项：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A. 电子版----59美元。 B. 纸质版----125美元。 C. 纸质版＋电子版----125美元。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>他愣住了。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>B 和 C，价格一模一样。一个只给纸质版，一个纸质版加电子版全送。谁会选 B？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>傻子都不会啊。但艾瑞里没有笑，马上意识到这是一个绝妙的设计。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>他拿着这三个选项，走进了麻省理工学院（MIT）的课堂，做了一个实验，让100个学生对这三个选项进行选择。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>结果：16%的学生选了 A，0%选了B，84%选了C。订阅费总收入：11,444美元。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>跟预想的一样，没有一个人选 B。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>然后艾瑞里做了一件小事：他把 B 删了，只留 A 和 C。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>逻辑上，一个从来没人选的东西，删掉它不应该影响任何结果，对吧？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>结果出来了：68%选了 A，32%选了 C。订阅费总收入暴跌到8,012美元。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这就是选项 B 的作用。它从来没人选，自己一份都没卖出去，却在暗中帮旁边的最贵的 C 套餐，多卖了52%。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>仅仅因为它的&quot;存在&quot;，就让杂志社多赚了3,432美元。这就是行为经济学中著名的&quot;诱饵效应&quot;。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>原理很简单：人类不擅长判断一个东西的&quot;绝对价值&quot;，但极其擅长做&quot;相对比较&quot;。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>当只有59美元和125美元两个选项时，你的大脑在比较&quot;便宜 vs 贵&quot;，大多数人选便宜的。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>但当&quot;125美元只买纸质版&quot;这个诱饵一出现，你的大脑就不比较 A 和 C 了，它开始比较 B 和 C。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>同样的价格，C 多了一个电子版。天哪，这不是白捡的吗！于是你心满意足地选了 C。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>浑然不知自己刚刚多花了66美元----买了一本可能一辈子都不会翻开的纸质杂志。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这个套路如今无处不在。咖啡店的中杯定价，只是为了让你觉得大杯&quot;更划算&quot;。视频网站的月卡，贵到让你觉得年卡&quot;不买就亏&quot;。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>手机发布会上，永远有一款&quot;高价低配&quot;机型，它唯一的使命，就是让旁边那款旗舰机型看起来&quot;性价比极高&quot;。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>当你觉得自己占了便宜的时候，多半是有人精心摆放了一个诱饵，让你心甘情愿走进了更贵的那扇门。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>那个没人选的选项，才是全场真正的主角。</span></span></code></pre></div><hr><h1 id="_353期" tabindex="-1">353期 <a class="header-anchor" href="#_353期" aria-label="Permalink to “353期”">​</a></h1><p><a href="https://www.seangoedecke.com/glue-work-considered-harmful/" target="_blank" rel="noreferrer">胶水工作重要吗？</a></p><blockquote><p>胶水工作重要吗？ &quot;胶水工作&quot;（glue work）指的是，帮助做出产品、提高效率的一些辅助工作。 举例来说，更新文档、解决技术债务、培训新人、维护团队成员的正常交流等等，都属于胶水工作。每个团队都需要大量这类工作。 我认为，<strong>胶水工作非常重要，如果没有它们来粘合整个团队，就很难做出大型产品，也无法减少大型组织中的摩擦。</strong> 有些工程师因此很天真，将大量精力花在这些胶水工作。但是，在晋升或发放奖金时，这些工程师往往被忽视，公司更看重那些销售直接相关的工作（如开发新功能）的工程师。 为什么胶水工作不能让你得到晋升呢？ 是因为公司太愚蠢，看不到这些工作的价值吗？我不这么认为。 <strong>公司不奖励胶水工作，因为他们不想让你优先考虑它，而想让你更重视产品的发布</strong>。胶水工作很辛苦。如果你有能力做好胶水工作，他们希望你把这种能力用在产品发布，而不是提高团队效率。 你必须明白，<strong>让团队更顺利地运行不是你的工作，你的真正工作是执行公司领导层的使命。</strong> 有一个很少人知道的事实是，与其花大量时间提高团队效率，不如让团队以60%的效率运行。 这里有两个主要原因。 （1）如果团队以100%的效率运行，团队成员不可避免地会精疲力尽，这对每个人都不好。 （2）最好让团队成员习惯于在公司的基本效率水平上运作，而不是在短时间内人为地消除摩擦。因为低摩擦的状态不可能长期持续，这要求巨大的投入。 大型科技公司在任何时间内都以大约20%-60%的效率运行（公司越大，运行效率越低）。大公司的增长主要在于占据更多的市场，而不在于提高效率，所以公司不在意让团队效率提高到一个很高的水平。另一方面，如果个别员工愿意在胶水工作上投入大量时间，将团队的效率提升到80%或90%，公司将利用这种免费价值，但公司对长期锁定这种价值没有任何真正的兴趣，因为这取决于优秀的人才自愿奉献时间，是不可持续的。 所以，结论就是，公司需要有一些胶水工作，但是不需要太多的胶水工作。 作为开发者，你的正确做法应该是，<strong>在战术层面上做一些胶水工作，而不能把胶水工作提高到战略层面</strong>。 也就是说，你应该把胶水工作视为额外工作，你的关注重点永远应该是项目的成功。你不会因为胶水工作而得到特别的奖励，但你会因为项目的成功而获得奖励。</p></blockquote><hr><h1 id="言论" tabindex="-1">言论 <a class="header-anchor" href="#言论" aria-label="Permalink to “言论”">​</a></h1><h2 id="一个乐观主义者的专访" tabindex="-1">一个乐观主义者的专访 <a class="header-anchor" href="#一个乐观主义者的专访" aria-label="Permalink to “一个乐观主义者的专访”">​</a></h2><ul><li><code>长期中，未来由乐观主义者决定。</code></li><li><strong>悲观者正确，乐观者成功</strong>：成为一个&quot;行动主义者&quot;。 你可以是悲观，但还的是要像乐观主义者一样去做事。个人无法影响历史，未来根本不取决于你的看法，不管你乐观还是悲观，历史都会一样地发生。真正影响你的，是个人的成功和失败。个人的出路只能是积极动手去做，为自己创造一些改变，争取更好一点的处境。</li><li>悲观者看不到希望，就不去做事了，所以什么也不会改变，悲观预言就成真了；乐观者愿意做事，做了才有可能成功，所以成功属于乐观者</li></ul><h2 id="人生的意义" tabindex="-1">人生的意义 <a class="header-anchor" href="#人生的意义" aria-label="Permalink to “人生的意义”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你无事可做时，未来看起来就会让人灰心丧气。我早已放弃了为人生寻找某种意义之类的事情，但我确实尝试寻找一些有趣的事情来做。</span></span>
<span class="line"><span>人生有没有意义？人类又有什么意义？</span></span>
<span class="line"><span>我说，人生是有意义的，而人类则是没有意义的。</span></span>
<span class="line"><span>询问人类的存在有没有意义，就等于询问地球或宇宙的存在有没有意义一样，是得不到答案的。</span></span>
<span class="line"><span>人生的意义是什么呢？它的意义就在于为没有意义的人类工作、服务等等，其目的不外乎是使人类生活得更好并得以延续。</span></span>
<span class="line"><span>反正人类是现实的存在，你又是其中一员，你有义务使它发展延续。你只要这样做了，你的人生就具有了意义，或者说价值，并不一定要去理会人类存在的意义。</span></span></code></pre></div><ul><li>大家看明白，他的意思吗？他的意思是，要想通人生的意义，就要先想通人类的意义。但是他认为，人类作为一个物种，是没有意义的，就像你问恐龙的意义是什么一样。 但是，人类既然存在了，你就没有选择。你的人生意义就是帮助其他人、乃至人类这个物种的生存和发展。因此，实现人生意义的最好方法，就是做对社会有益的事情，让社会和人类延续。最低限度上，只要正常的劳动和工作，你的人生就有意义了。 大家同意他的这个说法吗？</li><li>我觉得对我很有启发，让我想通了，一件事可以在宏观上没有意义，但是在微观上有意义。</li><li>西方哲学有一个流派，叫做&quot;存在主义&quot;，认为世界是荒谬的。我也有这种感觉，经常产生无力感，一方面觉得徒劳，不可能逃脱，另一方面又觉得必须做点什么。</li><li>这篇短文更让我确信，不能停下来，你唯一的出路（或者说对抗方法），就是保持工作，做一点有益于社会的事情，只有这样才能在没有意义的世界里找到一点意义。</li></ul><h2 id="珍惜时间" tabindex="-1">珍惜时间 <a class="header-anchor" href="#珍惜时间" aria-label="Permalink to “珍惜时间”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>他写道：&quot;一周是一年的2%。&quot;</span></span></code></pre></div><ul><li>我一直觉得，每周七天是很短的时间，尤其是发布周刊以后，更是过得飞快。但是，他的这句话让我意识到，每周其实是一年当中很重要的组成部分。虚度一周就是虚度一年的2%。你没有几周可以虚度的。只要多浪费几周，这一年很快过去。反过来，过好这一周，那么这一年的2%就有价值了。只要这样多过几周，一年就会变得很充实，有拿得出手的成果。</li><li>我坚持写周刊，每周记录一点东西，整理一些思考，现在想起来，其实就是在督促自己过好这一年的2%。</li><li>真正决定一个人是否宽容，是下面三个因素。 思维灵活、个性不固执 、专注。这就是说，如果某人容易接受新观点（思维灵活），不固执已见，也不容易分心（专注），他很可能是一个宽容的人</li></ul><h2 id="其他-1" tabindex="-1">其他 <a class="header-anchor" href="#其他-1" aria-label="Permalink to “其他”">​</a></h2><ul><li>痛苦能滋养勇气。如果只有美好的事情发生在你身上，你就不可能变得勇敢</li><li>幸福的三大要素是：有要做的事（something to do）、有要爱的人（someone to love）、有寄予希望的东西（something to hope for）</li><li>一个艺术家得了晚期癌症，即将死去。一位经常采访他的主持人问他：你现在对生死有什么新的理解吗？ <ul><li>他回答：你知道吗，吃三明治是一件多享受的事情。</li><li>我现在感觉生活更珍贵了，时刻提醒自己要珍惜每一份三明治，每一分钟，以及所有的一切。</li></ul></li><li>我担心，以后在重要的媒体中，实质性内容将逐渐衰落，30秒的片段会流行，节目只具有最低的共识，充斥着对伪科学和迷信的盲目介绍，尤其还有一种对无知的庆祝。-- 卡尔·萨根，美国著名科普作家，这段话写于1994年</li></ul>`,67)])])}const b=l(i,[["render",r]]);export{u as __pageData,b as default};
